-- Subconjunto del esquema REAL de Supabase para probar el panel de consulta, con las columnas
-- leídas de information_schema el 2026-11-04. Es solo para pruebas (NO es una migración y nunca
-- se ejecuta contra Supabase).
--
-- Va aparte de esquema_base.sql porque aquel es anterior al modelo actual: ahí `events` no tiene
-- fecha, hora ni cliente, y `quote.hour` es obligatoria.

create table public.users (
    id bigint generated by default as identity primary key,
    email varchar not null unique,
    name varchar not null,
    phone varchar,
    documento text
);

create table public.venue (
    id bigint generated by default as identity primary key,
    name varchar not null,
    city text
);

create table public.transportation (
    id bigint generated by default as identity primary key,
    city varchar not null,
    price numeric not null default 0
);

create table public.quote (
    id bigint generated by default as identity primary key,
    total numeric not null default 0 check (total >= 0),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    estado text not null default 'recibida'
        check (estado in ('recibida', 'en_revision', 'finalizada', 'cancelada')),
    client_id bigint references public.users (id),
    event_type varchar,
    venue_id bigint references public.venue (id),
    transportation_id bigint references public.transportation (id),
    date date,
    venue_nombre_manual text,
    address text,
    hour time,
    venue_direccion_manual text
);

create table public.events (
    id bigint generated by default as identity primary key,
    quote_id bigint not null unique references public.quote (id) on delete cascade,
    confirmed boolean not null default false,
    initial_payment boolean not null default false,
    total_paid numeric not null default 0,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    contrato_enviado_en timestamptz,
    contrato_firmado_nombre text,
    contrato_firmado_subido_en timestamptz,
    venue_id bigint references public.venue (id),
    transportation_id bigint references public.transportation (id),
    event_type varchar,
    address varchar,
    date date,
    hour time,
    client_id bigint references public.users (id),
    venue_nombre_manual text,
    venue_direccion_manual text
);
